import assert from "node:assert/strict";
import { readFile } from "node:fs/promises";
import { it } from "node:test";
import { PdfDocument } from "@poe-code/pdf-ast";
import { MemoryFileSystem } from "@poe-code/safe-fs/core";
import { docxMetadata, docxDocumentPrefix, docxDocumentSuffix } from "./docx-parts.js";
import { createStoredZipArchive, runSofficeCli, runSofficeFileCli } from "./index.js";

// Fixture generated by Pandoc 3.9 from "- Apple\n- Banana\n\n1. Plan\n2. Execute\n".
for (const format of ["txt", "html", "pdf"]) it(`preserves real Pandoc DOCX bullet and ordered lists in ${format}`, async () => {
  const bytes = new Uint8Array(await readFile(new URL("./fixtures/lists.docx", import.meta.url)));
  const files = new Map([["/input.docx", bytes]]);
  const result = await runSofficeCli(["--headless", "--convert-to", format, "--outdir", "/out", "/input.docx"], files);
  assert.equal(result.exitCode, 0, result.stderr);
  const fs = new MemoryFileSystem();
  await fs.writeFile("/input.docx", bytes);
  const fileResult = await runSofficeFileCli(["--convert-to", format, "--outdir", "/out", "/input.docx"], {
    filesystem: fs, stdout: { async write() {} }, stderr: { async write() {} }
  });
  assert.equal(fileResult.exitCode, 0);
  const output = files.get(`/out/input.${format}`)!;
  const fileOutput = await fs.readFile(`/out/input.${format}`);
  if (format === "pdf") assert.equal(PdfDocument.load(fileOutput).extractText(), PdfDocument.load(output).extractText());
  else assert.deepEqual(fileOutput, output);
  const text = format === "pdf" ? PdfDocument.load(output).extractText() : new TextDecoder().decode(output);
  if (format === "html") {
    assert.ok(text.includes("<ul>\n<li>Apple</li>\n<li>Banana</li>\n</ul>"), text);
    assert.ok(text.includes('<ol start="1">\n<li value="1">Plan</li>\n<li value="2">Execute</li>\n</ol>'), text);
  } else for (const item of ["• Apple", "• Banana", "1. Plan", "2. Execute"]) assert.ok(text.includes(item), text);
});

for (const format of ["txt", "html", "pdf"]) it(`preserves DOCX starts, nesting, continuation and independent lists in ${format}`, async () => {
  const paragraph = (text: string, id?: number, level = 0) => `<w:p>${id === undefined ? "" : `<w:pPr><w:numPr><w:ilvl w:val="${level}"/><w:numId w:val="${id}"/></w:numPr></w:pPr>`}<w:r><w:t>${text}</w:t></w:r></w:p>`;
  const bytes = createStoredZipArchive(Object.fromEntries(Object.entries({
    ...docxMetadata,
    "word/document.xml": docxDocumentPrefix + paragraph("First", 1) + paragraph("Child", 1, 1) + paragraph("Second", 1) + paragraph("Another child", 1, 1) + paragraph("Break") + paragraph("Continued", 1) + paragraph("Restart", 2) + paragraph("Plain", 0) + docxDocumentSuffix,
    "word/numbering.xml": '<w:numbering xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:abstractNum w:abstractNumId="1"><w:lvl w:ilvl="0"><w:start w:val="1"/><w:numFmt w:val="decimal"/><w:lvlText w:val="%1."/></w:lvl><w:lvl w:ilvl="1"><w:start w:val="1"/><w:numFmt w:val="decimal"/><w:lvlText w:val="%1.%2."/></w:lvl></w:abstractNum><w:num w:numId="1"><w:abstractNumId w:val="1"/><w:lvlOverride w:ilvl="0"><w:startOverride w:val="4"/></w:lvlOverride></w:num><w:num w:numId="2"><w:abstractNumId w:val="1"/></w:num></w:numbering>'
  }).map(([path, text]) => [path, new TextEncoder().encode(text)])));
  const files = new Map([["/input.docx", bytes]]);
  const result = await runSofficeCli(["--convert-to", format, "/input.docx"], files);
  assert.equal(result.exitCode, 0, result.stderr);
  const output = files.get(`/input.${format}`)!;
  const text = format === "pdf" ? PdfDocument.load(output).extractText() : new TextDecoder().decode(output);
  if (format === "html") {
    assert.ok(text.includes('<ol start="4">\n<li value="4">First<ol start="1">'), text);
    assert.ok(text.includes('</ol>\n<p>Break</p>\n<ol start="6">'), text);
    assert.ok(text.includes('<ol start="1">\n<li value="1">Restart</li>\n</ol>\n<p>Plain</p>'), text);
  } else for (const item of ["4. First", "4.1. Child", "5. Second", "5.1. Another child", "6. Continued", "1. Restart"]) assert.ok(text.includes(item), text);
});

it("preserves DOCX lists when converting alongside a plain text input", async () => {
  const bytes = new Uint8Array(await readFile(new URL("./fixtures/lists.docx", import.meta.url)));
  const files = new Map([["/input.docx", bytes], ["/notes", new TextEncoder().encode("Notes")]]);
  const result = await runSofficeCli(["--convert-to", "txt", "/input.docx", "/notes"], files);
  assert.equal(result.exitCode, 0, result.stderr);
  assert.ok(new TextDecoder().decode(files.get("/input.txt")).includes("2. Execute"));
  assert.equal(new TextDecoder().decode(files.get("/notes.txt")), "Notes");
});
